import React from "react";
import '../style.css/Services.css';



const Services =() => {
    return(
      <main>
        <div>
          <h1>Ma page services</h1>
          <img src="../images/banner.jpg" alt="fond violet avec un eclair blanc"></img>
        </div>
      </main>
    );
      
    
}

export default Services;
